--
-- Modül yamaları KALDIRILDI (2026-07-25) — artık gereksiz ve ZARARLIYDI.
--
-- Bu bölümde zamanla eklenmiş 7 adet "idempotent" INSERT INTO modules yaması vardı.
-- Yukarıdaki COPY bloğu üretimden yeniden üretildiğinde (50 modülün tamamı) yamalar
-- hem gereksizleşti hem ÇAKIŞTI: seed'in yama id'leri üretimden kaymıştı
--   (system.docs seed=914 / üretim=915; stok.* seed=904-908 / üretim=905-909)
-- → `ON CONFLICT (id) DO NOTHING` farklı id'yi yakalamıyor, `ix_modules_code` UNIQUE
--   patlıyordu ve bootstrap 4/5 adımda ölüyordu.
--
-- KURAL: yeni modül eklenince bu dosyaya YAMA EKLEME — COPY bloğunu üretimden
-- yeniden üret (modules + role_module_permissions), tek kaynak orası kalsın.
--
SELECT pg_catalog.setval('public.modules_id_seq',
       GREATEST((SELECT max(id) FROM public.modules), 1), true);
SELECT pg_catalog.setval('public.role_module_permissions_id_seq',
       GREATEST((SELECT max(id) FROM public.role_module_permissions), 1), true);
